package org.beyondlight;
import java.util.*;
/** Small bounded JSON reader/writer for local scientific records; no executable input. */
public final class Json {
 private Json(){}
 public static Object parse(String s){if(s.length()>12_000_000)throw new IllegalArgumentException("JSON exceeds 12 MB import limit");P p=new P(s);Object o=p.value(0);p.ws();if(p.i<s.length())throw p.bad("trailing data");return o;}
 public static String stringify(Object o){StringBuilder b=new StringBuilder();write(b,o);return b.toString();}
 private static void write(StringBuilder b,Object o){if(o==null){b.append("null");return;}if(o instanceof String s){b.append('"');for(char c:s.toCharArray()){switch(c){case '"'->b.append("\\\"");case '\\'->b.append("\\\\");case '\n'->b.append("\\n");case '\r'->b.append("\\r");case '\t'->b.append("\\t");default->{if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);}}}b.append('"');return;}if(o instanceof Number n){if(!Double.isFinite(n.doubleValue()))throw new IllegalArgumentException("nonfinite JSON number");b.append(n);return;}if(o instanceof Boolean){b.append(o);return;}if(o instanceof Map<?,?>m){b.append('{');boolean first=true;for(var e:m.entrySet()){if(!first)b.append(',');first=false;write(b,String.valueOf(e.getKey()));b.append(':');write(b,e.getValue());}b.append('}');return;}if(o instanceof Iterable<?>a){b.append('[');boolean first=true;for(Object x:a){if(!first)b.append(',');first=false;write(b,x);}b.append(']');return;}throw new IllegalArgumentException("unsupported JSON value type");}
 private static final class P {final String s;int i;P(String s){this.s=s;}void ws(){while(i<s.length()&&Character.isWhitespace(s.charAt(i)))i++;}IllegalArgumentException bad(String x){return new IllegalArgumentException(x+" at character "+i);}Object value(int depth){if(depth>40)throw bad("JSON nesting exceeds limit");ws();if(i>=s.length())throw bad("unexpected end");char c=s.charAt(i);if(c=='"')return str();if(c=='{')return obj(depth+1);if(c=='[')return arr(depth+1);if(s.startsWith("true",i)){i+=4;return true;}if(s.startsWith("false",i)){i+=5;return false;}if(s.startsWith("null",i)){i+=4;return null;}return num();}String str(){i++;StringBuilder b=new StringBuilder();while(i<s.length()){char c=s.charAt(i++);if(c=='"')return b.toString();if(c=='\\'){if(i>=s.length())throw bad("bad escape");char e=s.charAt(i++);switch(e){case '"','\\','/'->b.append(e);case 'b'->b.append('\b');case 'f'->b.append('\f');case 'n'->b.append('\n');case 'r'->b.append('\r');case 't'->b.append('\t');case 'u'->{if(i+4>s.length())throw bad("bad unicode escape");b.append((char)Integer.parseInt(s.substring(i,i+4),16));i+=4;}default->throw bad("bad escape");}}else b.append(c);}throw bad("unterminated string");}Map<String,Object>obj(int d){i++;Map<String,Object>m=new LinkedHashMap<>();ws();if(i<s.length()&&s.charAt(i)=='}'){i++;return m;}while(true){ws();if(i>=s.length()||s.charAt(i)!='"')throw bad("object key expected");String k=str();ws();if(i>=s.length()||s.charAt(i++)!=':')throw bad(": expected");m.put(k,value(d));ws();if(i<s.length()&&s.charAt(i)=='}'){i++;return m;}if(i>=s.length()||s.charAt(i++)!=',')throw bad(", expected");}}List<Object>arr(int d){i++;List<Object>a=new ArrayList<>();ws();if(i<s.length()&&s.charAt(i)==']'){i++;return a;}while(true){a.add(value(d));ws();if(i<s.length()&&s.charAt(i)==']'){i++;return a;}if(i>=s.length()||s.charAt(i++)!=',')throw bad(", expected");}}Number num(){int a=i;if(i<s.length()&&s.charAt(i)=='-')i++;while(i<s.length()&&Character.isDigit(s.charAt(i)))i++;if(i<s.length()&&s.charAt(i)=='.'){i++;while(i<s.length()&&Character.isDigit(s.charAt(i)))i++;}if(i<s.length()&&(s.charAt(i)=='e'||s.charAt(i)=='E')){i++;if(i<s.length()&&(s.charAt(i)=='+'||s.charAt(i)=='-'))i++;while(i<s.length()&&Character.isDigit(s.charAt(i)))i++;}try{return Double.parseDouble(s.substring(a,i));}catch(Exception e){throw bad("invalid number");}}}
 @SuppressWarnings("unchecked") public static Map<String,Object> map(Object o){if(!(o instanceof Map))throw new IllegalArgumentException("JSON object expected");return (Map<String,Object>)o;}
}
